def transform(grid):
    """Transform 0s to 8s, 8s near 0s become 3s, others stay same."""
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    # First pass: find original 0 positions
    zero_positions = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                zero_positions.add((r, c))

    # Second pass: apply transformation
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 0:
                result[r][c] = 8
            elif val == 8:
                # Check if within Manhattan distance 2 of any 0 in original grid
                near_zero = False
                for zr, _ in zero_positions:
                    if abs(r - zr) <= 2:
                        near_zero = True
                        break
                if near_zero:
                    result[r][c] = 3
                else:
                    result[r][c] = 8
            else:
                result[r][c] = val

    return result


